func _build_tiles() -> void:
	for index: int in range(TILE_PATHS.size()):
		var tile := _make_sprite("HandoffBackground_r%d_c%d" % [
			index / TILE_COLUMNS, index % TILE_COLUMNS], TILE_PATHS[index])
		if tile == null:
			continue
		tile.z_index = -20
		_tiles.append(tile)
		_world.add_child(tile)

func _refresh_state() -> void:
	var house_visible := _state == "butterfly_house"
	if _walkway != null:
		_walkway.visible = true
	if _house != null:
		_house.visible = true
	if _house_button != null:
		_house_button.visible = house_visible
	if _roshan != null:
		_roshan.visible = true
		_update_roshan_position()
	if _pointer != null:
		_pointer.visible = true
		if house_visible:
			_pointer_base = HOUSE_HOTSPOT.get_center() + Vector2(-44.0, -88.0)
		elif _state == "rainbow_return":
			_pointer_base = _return_waypoint() + Vector2(-42.0, -82.0)
		else:
			_pointer_base = _next_waypoint() + Vector2(-42.0, -82.0)
		_pointer.position = _pointer_base

func _handle_logical_tap(logical_position: Vector2) -> void:
	if _finished:
		return
	if _state == "butterfly_house":
		if HOUSE_HOTSPOT.has_point(logical_position):
			_enter_house()
		return
	if _state == "rainbow_return":
		var return_target := _return_waypoint()
		var return_touch := Rect2(return_target - MIN_TOUCH * 0.5, MIN_TOUCH)
		if not return_touch.has_point(logical_position):
			return
		_waypoint_index = maxi(_waypoint_index - 1, 0)
		if _main != null and is_instance_valid(_main) \
				and _main.has_method("_ui_tap"):
			_main.call("_ui_tap")
		if _waypoint_index <= 0:
			_finish("back")
		else:
			_refresh_state()
		return
	var next := _next_waypoint()
	var touch_size := Rect2(next - MIN_TOUCH * 0.5, MIN_TOUCH)
	if touch_size.has_point(logical_position):
		_waypoint_index = mini(_waypoint_index + 1, WALK_WAYPOINTS.size())
		if _main != null and is_instance_valid(_main) \
				and _main.has_method("_ui_tap"):
			_main.call("_ui_tap")
		if _waypoint_index >= WALK_WAYPOINTS.size():
			_state = "butterfly_house"
			_announce_state()
		_refresh_state()

func _capture_fairy_conservatory_return_context() -> void:
	var context := {
		"kind": "ocean",
		"position": player.position,
		"hud_visible": hud_layer != null and hud_layer.visible,
	}
	if game == "level2":
		var phase := String(g.get("phase", ""))
		if phase == "hall":
			context = {
				"kind": "hall",
				"room": castle_room_id,
				"position": player.position,
				"l2_open": l2_open,
				"hud_visible": hud_layer != null and hud_layer.visible,
			}
			if _castle_rooms_ref().is_open():
				_castle_rooms_ref().suspend()
		elif phase == "promenade":
			_capture_lagoon_trip_return()
			context = {
				"kind": "level2",
				"position": player.position,
				"l2_open": l2_open,
				"master_x": lagoon_trip_return_master_x,
				"hud_visible": hud_layer != null and hud_layer.visible,
			}
	elif game == "kart" and kart_from == "level2":
		context = {
			"kind": "level2",
			"position": player.position,
			"l2_open": galaxy_level2_open or l2_open,
			"master_x": lagoon_trip_return_master_x,
			"hud_visible": hud_layer != null and hud_layer.visible,
		}
		kart_from = ""
	fairy_conservatory_return_context = context

func _teardown(completed: bool) -> void:
	var earned_completion: bool = completed or _state == "won"
	_state = "done"
	if _prev_env != null and "we_node" in _main and _main.we_node != null:
		_main.we_node.environment = _prev_env
	if _player_node != null and "cam" in _player_node and _player_node.cam != null:
		(_player_node.cam as Camera3D).make_current()
	if _finish_cb.is_valid():
		_finish_cb.call(earned_completion)
	queue_free()
